insert into public.questions (id, subject, grade, category, difficulty, body, answer, distractors, explanation, image_url) values
  ('sci_1_b3_001', '理科', 1, '身のまわりの物質', 1, '水にとけにくい気体を集めるのに最も適した集め方はどれか。', '水上置換法', array['上方置換法', '下方置換法', 'ろ過'], '水にとけにくい気体は、水と置きかえて集める水上置換法が適している。ろ過は液体中の固体を分ける操作で、気体の集め方ではない。', null),
  ('sci_1_b3_002', '理科', 1, '身のまわりの物質', 2, '水にとけやすく、空気より密度が小さい気体を集めるのに適した集め方はどれか。', '上方置換法', array['下方置換法', '水上置換法', '蒸留'], '水にとけやすく空気より軽い気体は、容器の上方にたまるので上方置換法で集める。代表例はアンモニアである。', null),
  ('sci_1_b3_003', '理科', 1, '身のまわりの物質', 2, '水にとけやすく、空気より密度が大きい気体を集めるのに適した集め方はどれか。', '下方置換法', array['上方置換法', '水上置換法', '再結晶'], '水にとけやすく空気より重い気体は、容器の下方にたまるので下方置換法で集める。代表例は塩化水素である。', null),
  ('sci_1_b3_004', '理科', 1, '身のまわりの物質', 2, '気体を発生させて集めるとき、最初に出てくる気体を集めないほうがよい理由として正しいものはどれか。', '装置の中にあった空気が混ざっているから', array['最初の気体は温度が高すぎるから', '最初の気体には色がついているから', '最初の気体はにおいが強いから'], '発生し始めは装置内にあった空気が混ざって出てくるため、純粋な気体を集めるにはしばらくしてから集める。', null),
  ('sci_1_b3_005', '理科', 1, '身のまわりの物質', 1, '石灰石にうすい塩酸を加えると発生する気体は何か。', '二酸化炭素', array['酸素', '水素', 'アンモニア'], '石灰石にうすい塩酸を加えると二酸化炭素が発生する。石灰石のかわりに貝がらや卵の殻を使うこともできる。', null),
  ('sci_1_b3_006', '理科', 1, '身のまわりの物質', 1, '二酸化炭素を通すと白くにごる液体は何か。', '石灰水', array['食塩水', 'オキシドール', 'うすい塩酸'], '二酸化炭素を石灰水に通すと白くにごる。これは二酸化炭素を確かめる代表的な方法である。', null),
  ('sci_1_b3_007', '理科', 1, '身のまわりの物質', 2, '二酸化炭素が水にとけた水溶液は何性を示すか。', '酸性', array['中性', 'アルカリ性', '中性からアルカリ性'], '二酸化炭素が水にとけた水溶液（炭酸水）は酸性を示し、青色リトマス紙を赤色に変える。', null),
  ('sci_1_b3_008', '理科', 1, '身のまわりの物質', 2, '二酸化炭素のように、地球から放出される熱を吸収して地球の気温を保つはたらきをもつ気体を何というか。', '温室効果ガス', array['希ガス', '可燃性ガス', '助燃性ガス'], '二酸化炭素は温室効果ガスの一つで、増加しすぎると地球温暖化の原因になると考えられている。', null),
  ('sci_1_b3_009', '理科', 1, '身のまわりの物質', 2, '二酸化マンガンにうすい過酸化水素水（オキシドール）を加えると発生する気体は何か。', '酸素', array['水素', '二酸化炭素', '窒素'], '二酸化マンガンにオキシドールを加えると酸素が発生する。二酸化マンガンは反応を助けるはたらきをする。', null),
  ('sci_1_b3_010', '理科', 1, '身のまわりの物質', 2, '酸素を集めた集気びんの中に火のついた線香を入れると、どうなるか。', '線香が激しく燃える', array['線香の火がすぐに消える', '音を立てて爆発する', '変化しない'], '酸素には物を燃やすはたらき（助燃性）があるため、酸素中では線香が激しく燃える。', null),
  ('sci_1_b3_011', '理科', 1, '身のまわりの物質', 1, '亜鉛やマグネシウムなどの金属にうすい塩酸を加えると発生する気体は何か。', '水素', array['酸素', '二酸化炭素', 'アンモニア'], '亜鉛・マグネシウム・鉄・アルミニウムなどの金属にうすい塩酸（または硫酸）を加えると水素が発生する。', null),
  ('sci_1_b3_012', '理科', 1, '身のまわりの物質', 2, '水素を集めた試験管の口に火を近づけたときに起こることとして正しいものはどれか。', '音を立てて燃える', array['石灰水のように白くにごる', '赤色の炎が長く残る', '線香が激しく燃える'], '水素は可燃性の気体で、火を近づけると音を立てて燃え、水ができる。酸素のように物を燃やすはたらきはない。', null),
  ('sci_1_b3_013', '理科', 1, '身のまわりの物質', 2, '気体のうち、物質の中で最も密度が小さいものはどれか。', '水素', array['酸素', '二酸化炭素', '塩素'], '水素はすべての物質の中で最も密度が小さい。水にとけにくいため水上置換法で集める。', null),
  ('sci_1_b3_014', '理科', 1, '身のまわりの物質', 2, '塩化アンモニウムと水酸化カルシウムの混合物を加熱すると発生する気体は何か。', 'アンモニア', array['酸素', '水素', '二酸化炭素'], '塩化アンモニウムと水酸化カルシウムの混合物を加熱するとアンモニアが発生する。同時に水も発生する。', null),
  ('sci_1_b3_015', '理科', 1, '身のまわりの物質', 2, 'アンモニアの性質として正しいものはどれか。', '水に非常にとけやすく、刺激臭がある', array['水にとけにくく、においはない', '黄緑色で水にとけにくい', '空気より密度が大きく無臭である'], 'アンモニアは無色で刺激臭があり、水に非常にとけやすい。空気より密度が小さいため上方置換法で集める。', null),
  ('sci_1_b3_016', '理科', 1, '身のまわりの物質', 2, 'アンモニアを水に通したときの、水溶液の性質はどれか。', 'アルカリ性', array['酸性', '中性', '酸性からアルカリ性に変化する'], 'アンモニアが水にとけたアンモニア水はアルカリ性を示し、赤色リトマス紙を青色に変える。', null),
  ('sci_1_b3_017', '理科', 1, '身のまわりの物質', 3, 'アンモニアを集めた丸底フラスコにスポイトで水を入れると、水そうの水が噴水のように吹き上がった。この実験からわかるアンモニアの性質はどれか。', '水に非常にとけやすい', array['水に燃えやすい', '空気より密度が大きい', '水にとけにくい'], 'アンモニアが水に非常にとけやすいため、フラスコ内の気体が水にとけて圧力が下がり、水が吸い上げられて噴水になる。', null),
  ('sci_1_b3_018', '理科', 1, '身のまわりの物質', 1, '気体のにおいを確認するときの正しい方法はどれか。', '手であおぐようにしてかぐ', array['鼻を容器に近づけて深く吸う', '容器を直接口に当ててかぐ', '容器を加熱しながらかぐ'], '気体には有害なものもあるため、においは手であおぐようにして少量をかぐ。直接吸い込んではいけない。', null),
  ('sci_1_b3_019', '理科', 1, '身のまわりの物質', 2, '空気中に体積の割合で最も多く含まれている気体は何か。', '窒素', array['酸素', '二酸化炭素', 'アルゴン'], '空気は体積の割合でおよそ窒素が78%、酸素が21%を占める。窒素が最も多い。', null),
  ('sci_1_b3_020', '理科', 1, '身のまわりの物質', 2, '黄緑色で刺激臭があり、殺菌・漂白作用があるため水道水の消毒に使われる気体は何か。', '塩素', array['酸素', '水素', '窒素'], '塩素は黄緑色で刺激臭のある気体で、殺菌作用がある。水道水の消毒に使われ、くみ置きすると抜けていく。', null),
  ('sci_1_b3_021', '理科', 1, '身のまわりの物質', 2, '物を燃やすはたらきがある気体はどれか。', '酸素', array['水素', '窒素', '二酸化炭素'], '酸素には物を燃やすはたらき（助燃性）がある。水素は自分が燃え、二酸化炭素や窒素は物を燃やさない。', null),
  ('sci_1_b3_022', '理科', 1, '身のまわりの物質', 2, '次の気体のうち、水上置換法で集めるのに最も適したものはどれか。', '酸素', array['アンモニア', '塩化水素', '塩素'], '酸素や水素、窒素は水にとけにくいので水上置換法で集める。アンモニアや塩化水素、塩素は水にとけやすい。', null),
  ('sci_1_b3_023', '理科', 1, '身のまわりの物質', 2, '二酸化炭素の集め方として適しているものはどれか。', '下方置換法または水上置換法', array['上方置換法のみ', '上方置換法または水上置換法', '集め方はない'], '二酸化炭素は空気より密度が大きいため下方置換法で集められる。水に少ししかとけないので水上置換法でも集められる。', null),
  ('sci_1_b3_024', '理科', 1, '身のまわりの物質', 1, '無色・無臭で、空気中に体積で約21%含まれ、呼吸に使われる気体は何か。', '酸素', array['窒素', '二酸化炭素', '水素'], '酸素は無色・無臭で空気中に約21%含まれ、生物の呼吸や物の燃焼に使われる。', null),
  ('sci_1_b3_025', '理科', 1, '身のまわりの物質', 3, '肥料の原料や冷却剤に使われ、無色で刺激臭があり水に非常にとけやすい気体はどれか。', 'アンモニア', array['二酸化炭素', '酸素', '水素'], 'アンモニアは肥料の原料などに利用され、無色で刺激臭があり水に非常にとけやすい。この性質から上方置換法で集める。', null),
  ('sci_1_b3_026', '理科', 1, '水溶液', 1, '食塩水で、水にとけている食塩のように、液体にとけている物質を何というか。', '溶質', array['溶媒', '溶液', '結晶'], 'とけている物質を溶質、とかしている液体を溶媒、両者が均一に混ざった液体を溶液という。食塩水では食塩が溶質。', null),
  ('sci_1_b3_027', '理科', 1, '水溶液', 1, '食塩水で、食塩をとかしている水のように、溶質をとかす液体を何というか。', '溶媒', array['溶質', '溶液', '飽和水溶液'], '溶質をとかす液体を溶媒という。溶媒が水のときの溶液をとくに水溶液とよぶ。', null),
  ('sci_1_b3_028', '理科', 1, '水溶液', 2, '溶質が溶媒にとけて均一になった液体のうち、溶媒が水であるものをとくに何というか。', '水溶液', array['溶質', '溶媒', '懸濁液'], '溶質が溶媒に均一に混ざった液体を溶液といい、溶媒が水の場合をとくに水溶液という。', null),
  ('sci_1_b3_029', '理科', 1, '水溶液', 2, '塩酸は何という気体が水にとけたものか。', '塩化水素', array['二酸化炭素', 'アンモニア', '塩素'], '塩酸は気体の塩化水素が水にとけたもので、溶質は塩化水素である。炭酸水は二酸化炭素が水にとけたもの。', null),
  ('sci_1_b3_030', '理科', 1, '水溶液', 2, '水溶液の性質について、正しく述べているものはどれか。', '透明だが、色がついていることもある', array['必ず無色透明である', '時間がたつと下のほうが濃くなる', '必ず白くにごっている'], '水溶液は透明だが、硫酸銅水溶液のように色がついていることもある。均一なので放置しても濃さにかたよりは出ない。', null),
  ('sci_1_b3_031', '理科', 1, '水溶液', 2, '100gの水に25gの砂糖を完全にとかした。できた砂糖水の質量は何gか。', '125g', array['100g', '25g', '75g'], '砂糖がとけて見えなくなっても粒子はなくならないため、全体の質量は変わらない。100+25=125g。', null),
  ('sci_1_b3_032', '理科', 1, '水溶液', 2, '水にとけない固体を液体から分けるために、ろ紙とろうとを使ってこしとる操作を何というか。', 'ろ過', array['蒸留', '再結晶', '溶解'], 'ろ紙とろうとを使って液体から固体をこしとる操作をろ過という。水にとけない物質はろ紙に残り、とけた物質は通りぬける。', null),
  ('sci_1_b3_033', '理科', 1, '水溶液', 3, '水にデンプンとコーヒーシュガー（砂糖）を入れてかき混ぜ、ろ過した。ろ紙の上に残るものはどれか。', 'デンプン', array['コーヒーシュガー', '両方とも残る', 'どちらも残らない'], 'コーヒーシュガーは水にとけて粒子が小さくなりろ紙を通りぬける。デンプンは水にとけず粒子が大きいのでろ紙に残る。', null),
  ('sci_1_b3_034', '理科', 1, '水溶液', 2, 'ろ過の操作として正しいものはどれか。', '液はガラス棒を伝わらせて静かに注ぐ', array['ろうとの足はビーカーの壁につけない', '液はろ紙のふちいっぱいまで入れる', 'ろ紙は水でぬらさずに使う'], 'ろ過では液をガラス棒を伝わらせて注ぎ、ろうとの足のとがった側をビーカーの壁につける。ろ紙は水でぬらして密着させる。', null),
  ('sci_1_b3_035', '理科', 1, '水溶液', 2, '1種類の物質だけからできているものを純粋な物質（純物質）という。次のうち純粋な物質はどれか。', '二酸化炭素', array['食塩水', '空気', '石油'], '二酸化炭素は1種類の物質からなる純粋な物質。食塩水・空気・石油は2種類以上の物質が混ざった混合物である。', null),
  ('sci_1_b3_036', '理科', 1, '水溶液', 2, '2種類以上の物質が混ざり合ったものを混合物という。次のうち混合物はどれか。', '海水', array['酸化銀', '窒素', '二酸化炭素'], '海水は水やさまざまな物質が混ざった混合物である。酸化銀・窒素・二酸化炭素は1種類の物質からなる純粋な物質。', null),
  ('sci_1_b3_037', '理科', 1, '水溶液', 2, '水溶液の濃さを、溶液全体の質量に対する溶質の質量の割合で表したものを何というか。', '質量パーセント濃度', array['溶解度', '密度', '飽和度'], '質量パーセント濃度は、溶質の質量÷溶液全体の質量×100で求める、水溶液の濃さを表す値である。', null),
  ('sci_1_b3_038', '理科', 1, '水溶液', 2, '100gの水に25gの食塩をとかした食塩水の質量パーセント濃度は何%か。', '20%', array['25%', '4%', '75%'], '濃度=溶質の質量÷溶液全体の質量×100。25÷(100+25)×100=20%となる。', null),
  ('sci_1_b3_039', '理科', 1, '水溶液', 2, '質量パーセント濃度が10%の食塩水200gには、食塩が何gとけているか。', '20g', array['10g', '18g', '200g'], '溶質の質量=溶液の質量×濃度÷100。200×10÷100=20g。', null),
  ('sci_1_b3_040', '理科', 1, '水溶液', 3, '40gの砂糖を水にとかして質量パーセント濃度20%の砂糖水をつくるには、水を何g用意すればよいか。', '160g', array['200g', '40g', '80g'], '濃度20%なので溶液全体は40÷0.2=200g。そのうち砂糖が40gなので、水は200-40=160g必要。', null),
  ('sci_1_b3_041', '理科', 1, '水溶液', 2, '物質がそれ以上とけることができなくなった状態の水溶液を何というか。', '飽和水溶液', array['希薄水溶液', '混合物', '溶媒'], '物質が限度までとけてそれ以上とけなくなった水溶液を飽和水溶液という。', null),
  ('sci_1_b3_042', '理科', 1, '水溶液', 2, '100gの水に、ある物質をとかして飽和水溶液にしたときにとけた物質の質量を何というか。', '溶解度', array['質量パーセント濃度', '密度', '溶質'], '100gの水を飽和水溶液にするためにとけた物質の質量を溶解度という。一般に温度が上がると溶解度は大きくなる。', null),
  ('sci_1_b3_043', '理科', 1, '水溶液', 2, '水の温度と溶解度の関係をグラフに表したものを何というか。', '溶解度曲線', array['状態変化のグラフ', '濃度曲線', '融解曲線'], '水の温度ごとの溶解度をグラフに表したものを溶解度曲線という。物質ごとに曲線の形が異なる。', null),
  ('sci_1_b3_044', '理科', 1, '水溶液', 2, '一度水にとかした固体を、再び結晶としてとり出すことを何というか。', '再結晶', array['ろ過', '蒸留', '溶解'], '一度とかした固体を再び結晶としてとり出すことを再結晶という。物質をより純粋にする方法として利用される。', null),
  ('sci_1_b3_045', '理科', 1, '水溶液', 3, '水溶液の温度を下げて結晶をとり出す方法が適しているのは、次のうちどの物質か。', '硝酸カリウム', array['塩化ナトリウム', 'どちらも適している', 'どちらも適していない'], '硝酸カリウムは温度による溶解度の差が大きいため、冷やすと結晶が多く出る。塩化ナトリウムは温度で溶解度がほとんど変わらないので適さない。', null),
  ('sci_1_b3_046', '理科', 1, '水溶液', 3, '塩化ナトリウム（食塩）の水溶液から結晶をとり出すのに適した方法はどれか。', '水を蒸発させる', array['水溶液の温度を下げる', '水をさらに加える', 'ろ過する'], '塩化ナトリウムは温度による溶解度の変化が小さいため、冷やしても結晶がほとんど出ない。水を蒸発させて結晶をとり出す。', null),
  ('sci_1_b3_047', '理科', 1, '水溶液', 2, '物質がもつ、規則正しい形をした固体を何というか。', '結晶', array['溶質', '溶液', '沈殿'], '物質の種類によって決まった規則正しい形をした固体を結晶という。塩化ナトリウムや硝酸カリウムなど、物質ごとに形が異なる。', null),
  ('sci_1_b3_048', '理科', 1, '水溶液', 3, '60℃の硝酸カリウムの飽和水溶液と塩化ナトリウムの飽和水溶液を30℃まで冷やしたとき、出てくる結晶が多いのはどちらか。', '硝酸カリウム', array['塩化ナトリウム', 'どちらも同じ量', 'どちらも出てこない'], '硝酸カリウムは温度による溶解度の変化が大きいため、冷やすととけきれなくなった分が多く結晶として出てくる。', null),
  ('sci_1_b3_049', '理科', 1, '水溶液', 2, '砂糖は冷たい水にはあまりとけないが、お湯にはよくとける。このことからわかる温度と溶解度の関係として正しいものはどれか。', '温度が高くなると溶解度は大きくなる', array['温度が高くなると溶解度は小さくなる', '温度が変わっても溶解度は変わらない', '温度が低くなると溶解度は大きくなる'], '多くの物質は温度が高くなるほど溶解度が大きくなる。砂糖もお湯のほうが多くとけることからこの関係がわかる。', null),
  ('sci_1_b3_050', '理科', 1, '水溶液', 2, '水溶液を加熱して水を水蒸気にして追い出し、とけていた固体をとり出す操作を何というか。', '蒸発', array['ろ過', '凝固', '溶解'], '水溶液を加熱して水を蒸発させると、とけていた固体をとり出せる。塩化ナトリウムのように冷やしても結晶が出にくい物質に用いる。', null)
